      min-height: 100vh;
    }

    .page {
      width: min(1120px, calc(100% - 40px));
      margin: 0 auto;
      padding: 28px 0 56px;
    }

    header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      margin-bottom: 72px;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 12px;
      font-weight: 800;
      letter-spacing: -0.03em;
      font-size: 22px;
    }

    .logo {
      width: 38px;
      height: 38px;
      border-radius: 12px;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      box-shadow: 0 12px 36px rgba(124, 92, 255, 0.35);
    }

    nav {
      display: flex;
      align-items: center;
      gap: 10px;
      color: var(--muted);
      font-size: 14px;
    }

    nav span {
      padding: 9px 12px;
      border: 1px solid var(--border);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.04);
    }

    .hero {
      display: grid;
      grid-template-columns: 1.05fr 0.95fr;
      gap: 44px;
      align-items: center;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
      border-radius: 999px;
      border: 1px solid rgba(37, 214, 162, 0.34);
      background: rgba(37, 214, 162, 0.1);
      color: #bfffea;
      font-weight: 700;
      font-size: 13px;
      margin-bottom: 20px;
    }

    h1 {
      margin: 0;
      font-size: clamp(44px, 7vw, 78px);
      line-height: 0.92;
      letter-spacing: -0.075em;
    }

    .lead {
      max-width: 620px;
      margin: 24px 0 0;
      color: var(--muted);
      font-size: clamp(18px, 2vw, 22px);
      line-height: 1.5;
    }

    .nonce {
      display: inline-block;
      margin-top: 24px;
      padding: 12px 14px;
      border-radius: 14px;
      background: rgba(255, 255, 255, 0.09);
      border: 1px solid rgba(255, 255, 255, 0.18);
      color: #ffffff;
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
      font-size: 13px;
      overflow-wrap: anywhere;
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 30px;
    }

    .button {
      appearance: none;
      border: 0;
      border-radius: 14px;
      padding: 14px 18px;
      font-weight: 800;
      color: #080b14;
      background: linear-gradient(135deg, #ffffff, #dfe7ff);
      box-shadow: 0 18px 44px rgba(255, 255, 255, 0.14);
      text-decoration: none;
    }

    .button.secondary {
      color: var(--text);
      background: rgba(255, 255, 255, 0.08);
      border: 1px solid var(--border);
      box-shadow: none;
    }

    .card {
      position: relative;
      border: 1px solid var(--border);
      background: linear-gradient(180deg, var(--panel-2), var(--panel));
      border-radius: 28px;
      padding: 22px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .card::before {
      content: "";
      position: absolute;
      inset: -80px -60px auto auto;
      width: 210px;
      height: 210px;
      border-radius: 999px;
      background: rgba(124, 92, 255, 0.32);
      filter: blur(12px);
    }

    .window {
      position: relative;
      border-radius: 20px;
      background: #0d1327;
      border: 1px solid rgba(255, 255, 255, 0.12);
      overflow: hidden;
    }

    .bar {
      height: 42px;
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 0 14px;
      background: rgba(255, 255, 255, 0.06);
      border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    }

    .dot {
      width: 10px;
      height: 10px;
      border-radius: 999px;
      background: #ff5f57;
    }

    .dot:nth-child(2) { background: #ffbd2e; }
    .dot:nth-child(3) { background: #28c840; }

    .terminal {
      padding: 22px;
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
      font-size: 14px;
      line-height: 1.75;
      color: #cfe1ff;
    }

    .terminal .ok {
      color: #77f2c8;
    }

    .terminal .muted {
      color: #7f8cad;
    }

    .features {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
      margin-top: 54px;
    }

    .feature {
      padding: 20px;
      border-radius: 20px;
      background: rgba(255, 255, 255, 0.07);
      border: 1px solid var(--border);
    }

    .feature strong {
      display: block;
      margin-bottom: 8px;
      font-size: 16px;
    }

    .feature p {
      margin: 0;
      color: var(--muted);
      line-height: 1.5;
      font-size: 14px;
    }

    footer {
      margin-top: 54px;
      color: rgba(255, 255, 255, 0.52);
      font-size: 13px;
      text-align: center;
    }

    @media (max-width: 840px) {
      header {
        margin-bottom: 42px;
      }

      nav {
        display: none;
      }

      .hero {
        grid-template-columns: 1fr;
      }

      .features {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
